// src/components/AdminDashboard.jsx

import React, { useState, useEffect } from 'react';
// Assuming you have components for each section
import UserManagement from '../components/UserManagement'; 
import ItemReview from '../components/ItemReview';
import Analytics from '../components/Analytics';
import AuditLogs from '../components/AuditLogs';

const useAuth = () => ({
  user: {
    name: 'Admin User',
    // Role is key for RBAC
    role: 'super_admin' // Could be 'admin', 'moderator', etc.
  },
  // Function to check if the user has permission for a specific feature
  hasPermission: (requiredRoles) => {
    const userRole = 'super_admin'; // Replace with actual user role
    return requiredRoles.includes(userRole);
  }
});
// --------------------------------------------------

const AdminDashboard = () => {
  const { user, hasPermission } = useAuth();
  const [activeTab, setActiveTab] = useState('user-management');

  // Define tabs and their required roles for access
  const dashboardTabs = [
    { id: 'user-management', name: 'User Management', roles: ['super_admin'] },
    { id: 'item-review', name: 'Item Review & Claims', roles: ['super_admin', 'moderator'] },
    { id: 'analytics', name: 'System Analytics', roles: ['super_admin', 'analyst'] },
    { id: 'audit-logs', name: 'Audit Logs', roles: ['super_admin'] },
    // Add other necessary components like 'Send Notifications' as separate features or part of 'User Management'
  ];

  const renderContent = () => {
    switch (activeTab) {
      case 'user-management':
        return <UserManagement />;
      case 'item-review':
        return <ItemReview userRole={user.role} />;
      case 'analytics':
        return <Analytics />;
      case 'audit-logs':
        return <AuditLogs />;
      default:
        return <p>Select a tab.</p>;
    }
  };

  if (!user || !user.role) {
    return <div className="p-6 text-red-500">Access Denied. Please log in.</div>;
  }

  return (
    <div className="bg-gray-50 min-h-screen p-8">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Admin Panel</h1>
      
      {/* Tab Navigation */}
      <div className="flex border-b border-gray-200 mb-6">
        {dashboardTabs.map(tab => 
          // Only show tabs the user has permission for
          hasPermission(tab.roles) && (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`py-2 px-4 text-sm font-medium transition-colors duration-200 ${
                activeTab === tab.id
                  ? 'border-b-2 border-indigo-500 text-indigo-600'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              {tab.name}
            </button>
          )
        )}
      </div>

      {/* Main Content Area */}
      <div className="bg-white p-6 rounded-lg shadow-xl">
        {/* The content rendering is secured by the hasPermission check in the tabs */}
        {renderContent()}
      </div>
    </div>
  );
};

export default AdminDashboard;
